/**
 * @fileoverview Input-blocking utilities for automated browser interactions.
 *
 * While the browser agent is driving an interactive operation (click, fill,
 * press_key, etc.) we inject a transparent, full-viewport overlay that
 * intercepts user pointer/keyboard input. This prevents the human from
 * fighting the agent for control mid-action, which can cause flaky automation.
 *
 * The overlay is temporarily suspended for the duration of the actual tool
 * call (so chrome-devtools-mcp can drive the real page element) and resumed
 * immediately afterwards. It is always removed once the operation completes,
 * even if the operation fails.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE).
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input-blocking overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
