/**
 * Builds the JavaScript function string that suspends the input blocker.
 *
 * Disables pointer interception so an automated interactive tool call can
 * reach the real page element underneath. The overlay stays in the DOM.
 */
function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that resumes the input blocker after
 * an automated interactive tool call has completed.
 */
function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'auto';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input blocker.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Errors from the MCP call are swallowed and the promise resolves with
 * undefined so that a failure to block input never aborts the operation.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Suspends the input blocker (disables pointer interception) so an automated
 * interactive tool call can reach the underlying page element.
 */
export async function suspendInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    await browserManager.callTool(
      'evaluate_script',
      { function: buildSuspendScript() },
      signal,
    );
  } catch (error) {
    debugLogger.warn('Error suspending input blocker:', error);
    return undefined;
  }
}

/**
 * Resumes the input blocker (re-enables pointer interception) after an
 * automated interactive tool call has completed.
 */
export async function resumeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    await browserManager.callTool(
      'evaluate_script',
      { function: buildResumeScript() },
      signal,
    );
  } catch (error) {
    debugLogger.warn('Error resuming input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Errors from the MCP call are swallowed and the promise resolves with
 * undefined so cleanup never throws, even when the preceding operation failed.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}
